package io.quarkus.hibernate.accessor.runtime;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Registers an instance method for the Hibernate accessor factory, or configures this member category
 * through {@link ReflectionFreeAccessor}. The configured accessor strategy determines whether access
 * uses generated bytecode or reflection.
 * A member annotation overrides the type's settings for that member. Disabling registration here
 * does not cancel requests from other extensions.
 * <p>
 * A reader must have no parameters and a non-void return type; a writer must have exactly one
 * parameter, and its return value is ignored. Method names need not follow JavaBeans conventions.
 * An enabled annotation on a static method or a method with any other signature fails the build.
 */
@Retention(RetentionPolicy.CLASS)
@Target(ElementType.METHOD)
public @interface ReflectionFreeMethodAccessor {
    /** Whether annotation-based registration is enabled. */
    boolean enabled() default true;
}
